// app.js – Hardened version
require('dotenv').config();               // Load env vars from .env (dev convenience)
const express = require('express');
const helmet = require('helmet');         // Security headers
const cors = require('cors');             // CORS control
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // Structured logging (can be swapped for pino)

const app = express();

// ---------- Middleware ----------
app.use(helmet());                         // Sets X‑Content-Type-Options, CSP, HSTS, etc.
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' })); // Adjust per your domain
app.use(express.json({ limit: '1mb' }));   // Body parser with size limit

// Simple request logger (avoid in high‑throughput prod, replace with winston/pino)
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// Rate limiting – prevents brute‑force / DoS on public endpoints
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // No sensitive data – keep response tiny
  res.set('Cache-Control', 'no-store');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// In a real app, protect this route with auth (JWT, session, etc.)
app.get('/users', (req, res) => {
  // Example: hide email addresses unless the caller is authorized
  const users = [
    { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
    { id: 2, name: 'Bob', email: maskEmail('bob@example.com') },
  ];
  res.json(users);
});

function maskEmail(email) {
  // Very simple masking – replace local part with asterisks
  const [local, domain] = email.split('@');
  return `${'*'.repeat(local.length)}@${domain}`;
}

// ---------- Error handling ----------
app.use((req, res) => {
  // 404 fallback – no stack trace leakage
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => { // eslint-disable-line no-unused-vars
  // Central error logger
  console.error(err);
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

// ---------- Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`Server listening on port ${PORT}`);
});

module.exports = app;
```

### What each addition does

| Addition | Why it matters |
|----------|----------------|
| `helmet` | Adds a suite of security‑related HTTP headers (CSP, HSTS, X‑Frame‑Options, etc.). |
| `cors` | Explicitly controls which origins can call the API; avoid the default `*` in prod. |
| `express-rate-limit` | Throttles abusive request patterns – limits DoS/brute‑force. |
| `express.json({ limit })` | Prevents huge payload attacks. |
| `morgan` (or a structured logger) | Centralized request logging without leaking raw request bodies. |
| Environment‑based config (`process.env.PORT`, `NODE_ENV`) | Keeps secrets out of source code and lets you switch behaviour between dev/prod. |
| 404 & error middleware | Guarantees consistent JSON error responses and prevents stack‑trace leakage. |
| Email masking / authentication placeholder | Addresses the privacy leak of exposing raw email addresses. |
| `.env` support (`dotenv`) | Allows secret configuration (e.g., DB credentials, API keys) without hard‑coding them.

