// app.js – updated version

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------- Security middleware ----------
app.use(helmet());                           // Secure HTTP headers
app.use(cors({                               // Restrict origins in prod
  origin: process.env.CORS_ORIGIN || '*',   // Change '*' to your domain
}));
app.use(rateLimit({                         // Basic DoS protection
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,               // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
}));

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // TODO: protect with authentication/authorization
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  // Example: mask email if you cannot enforce auth yet
  const safeUsers = users.map(u => ({
    id: u.id,
    name: u.name,
    email: u.email.replace(/(.{2}).+(@.+)/, '$1***$2')
  }));
  res.json(safeUsers);
});

// ---------- Error handling ----------
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- Graceful shutdown ----------
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});
process.on('SIGTERM', () => {
  console.log('SIGTERM received – shutting down gracefully');
  server.close(() => process.exit(0));
});
process.on('SIGINT', () => {
  console.log('SIGINT received – shutting down gracefully');
  server.close(() => process.exit(0));
});

module.exports = app;
```

