## How to Refactor the Code

Below is an updated version of **app.js** that demonstrates the two most common hard‑coded values (the HTTP port and the user list) being externalized.

```js
/* ------------------------------------------------------------------
   app.js – minimal Express server with security hardening
------------------------------------------------------------------- */
const express = require('express');
const helmet   = require('helmet');
const cors     = require('cors');
const rateLimit = require('express-rate-limit');
const fs       = require('fs');
const path = require('path');

const app = express();

/* ---------- Security middleware ---------- */
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET']
}));
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

/* ---------- Simple auth placeholder ---------- */
function requireAuth(req, res, next) {
  if (!req.headers.authorization) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // TODO: replace with real token / session validation
  next();
}

/* ---------- Routes ---------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* Load user data from an external JSON file if it exists.
   This keeps the source code free of static PII.                     */
let users = [];
const usersFile = process.env.USER_DATA_PATH ||
                  path.join(__dirname, 'data', 'users.json');

if (fs.existsSync(usersFile)) {
  try {
    users = JSON.parse(fs.readFileSync(usersFile, 'utf8'));
  } catch (e) {
    console.error('Failed to parse user data file:', e);
  }
}

/* Protected endpoint – only reachable after auth middleware */
app.get('/users', requireAuth, (req, res) => {
  // In production you would filter / mask PII here
  res.json(users);
});

/* ---------- Central error handler ---------- */
app.use((err, _req, res, _next) => {
  console.error(err);
  const status = err.status || 500;
  const msg = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: msg });
});

/* ---------- Server start ---------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What changed?

